  "inlineSchema": "// Letchi Pharmacie — pharmacy management for Mauritius\n// SQLite for demo; keep types Postgres-portable (no SQLite-only features).\n//\n// Statutory core:\n// - Pharmacy Act 1983: every dispensed prescription goes in the Prescription Book,\n//   retained 2 years (model Dispensation).\n// - Dangerous Drugs Act 2000: storage + transaction records for dangerous drugs,\n//   kept for inspection (model DangerousDrugEntry, running balance).\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../lib/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n}\n\nmodel Pharmacy {\n  id             String   @id @default(cuid())\n  name           String\n  address        String\n  city           String\n  phone          String\n  licenceNo      String // Pharmacy Board licence number\n  pharmacistName String // responsible registered pharmacist\n  updatedAt      DateTime @updatedAt\n}\n\nmodel User {\n  id       String @id @default(cuid())\n  name     String\n  email    String @unique\n  role     String @default(\"pharmacist\")\n  initials String\n}\n\nmodel Medication {\n  id                 String  @id @default(cuid())\n  name               String // brand/label name, e.g. \"Paracétamol 500mg\"\n  dci                String // generic (DCI) name, e.g. \"paracetamol\"\n  form               String // TABLET | SYRUP | INJECTION | CREAM | CAPSULE | INHALER | SACHET\n  strength           String // \"500mg\", \"5mg/5ml\"…\n  isDangerousDrug    Boolean @default(false) // Dangerous Drugs Act 2000 schedule\n  isPrescriptionOnly Boolean @default(false) // POM: requires prescriber details\n  unitPriceCents     Int\n  reorderLevel       Int     @default(20)\n\n  batches       Batch[]\n  dispensations Dispensation[]\n  ddEntries     DangerousDrugEntry[]\n  saleLines     SaleLine[]\n}\n\nmodel Batch {\n  id           String     @id @default(cuid())\n  medicationId String\n  medication   Medication @relation(fields: [medicationId], references: [id])\n  lotNo        String\n  expiryDate   DateTime\n  quantity     Int // units remaining in this batch\n  receivedAt   DateTime   @default(now())\n  supplier     String\n\n  dispensations Dispensation[]\n  ddEntries     DangerousDrugEntry[]\n  saleLines     SaleLine[]\n}\n\n// One row = one line of the statutory Prescription Book (Pharmacy Act 1983, kept 2 years).\nmodel Dispensation {\n  id              String     @id @default(cuid())\n  patientName     String\n  patientNic      String? // national ID number, optional\n  prescriberName  String? // REQUIRED when the medication is prescription-only\n  prescriberRegNo String? // Medical Council registration number\n  medicationId    String\n  medication      Medication @relation(fields: [medicationId], references: [id])\n  batchId         String\n  batch           Batch      @relation(fields: [batchId], references: [id])\n  quantity        Int\n  dispensedAt     DateTime   @default(now())\n  pharmacist      String\n  priceCents      Int\n\n  ddEntry DangerousDrugEntry?\n}\n\n// Dangerous Drugs Register (Dangerous Drugs Act 2000). Auto-created on every\n// dispensation of a dangerous drug (quantityOut) and on every stock receipt\n// (quantityIn), carrying the per-medication running balance for inspection.\nmodel DangerousDrugEntry {\n  id             String        @id @default(cuid())\n  medicationId   String\n  medication     Medication    @relation(fields: [medicationId], references: [id])\n  batchId        String\n  batch          Batch         @relation(fields: [batchId], references: [id])\n  quantityIn     Int           @default(0)\n  quantityOut    Int           @default(0)\n  balanceAfter   Int\n  dispensationId String?       @unique\n  dispensation   Dispensation? @relation(fields: [dispensationId], references: [id])\n  timestamp      DateTime      @default(now())\n}\n\n// OTC counter sale (no prescription).\nmodel Sale {\n  id         String     @id @default(cuid())\n  totalCents Int        @default(0)\n  paidAt     DateTime   @default(now())\n  method     String     @default(\"cash\") // cash | card | mcb_juice | myt_money\n  lines      SaleLine[]\n}\n\nmodel SaleLine {\n  id           String     @id @default(cuid())\n  saleId       String\n  sale         Sale       @relation(fields: [saleId], references: [id], onDelete: Cascade)\n  medicationId String\n  medication   Medication @relation(fields: [medicationId], references: [id])\n  batchId      String\n  batch        Batch      @relation(fields: [batchId], references: [id])\n  quantity     Int\n  priceCents   Int // line total\n}\n\n// Infra standard: every mutation writes an audit row.\nmodel AuditLog {\n  id        String   @id @default(cuid())\n  actor     String\n  action    String // e.g. dispensation.create, stock.receive, sale.create\n  entity    String\n  entityId  String\n  detail    String // JSON snapshot of the change\n  createdAt DateTime @default(now())\n}\n",
